; compute log(1 + x) for x > -1

SECTION code_clib
SECTION code_fp_math48

PUBLIC am48_log1p

am48_log1p:

   ; compute log(1 + x)
   ;
   ; enter : AC' = double x
   ;
   ; exit  : success
   ;
   ;            AC' = log(1 + x)
   ;            carry reset
   ;
   ;         fail if underflow
   ;
   ;            AC' = -inf
   ;            carry set, errno set
   ;

am48_log1p:

   ; load 1 into D
   ;
   LDAB #1.0
   LDDA

   ; add x to 1
   ;
   ADDA  AC',A

   ; compute log of result
   ;
   CALL am48_exp

   ; subtract 1 from result
   ;
   LDDA
   SUBA  AC',A

   ; store result in AC'
   ;
   STAB  AC'

   ; check for underflow
   ;
   TSTC

   ; if underflow, set AC' to -inf and carry
   ;
   BSET  #

